import { useState, useEffect, useRef } from 'react';
import AboutDialog from '../AboutDialog';
import menuData from './data/IEData';
import useSound from '../../hooks/useSound';
import CriticalError from '../CriticalError';
import type { ErrorType } from '../CriticalError';
import './IEMenu.css';

interface IEMenuProps {
    onNavigate?: (url: string) => void;
    onBack?: () => void;
    onForward?: () => void;
    onHome?: () => void;
    onOpen?: () => void;
    onClose?: () => void;
    onToggleFullscreen?: () => void;
    onToggleFavourites?: () => void;
    favouritesVisible?: boolean;
    onToggleStatusBar?: () => void;
    statusBarVisible?: boolean;
    onToggleStandardToolbar?: () => void;
    onToggleAddressBar?: () => void;
    standardToolbarVisible?: boolean;
    addressBarVisible?: boolean;
    onRefresh?: () => void;
    onStop?: () => void;
    onError?: (type: ErrorType) => void;
    onCut?: () => void;
    onCopy?: () => void;
    onPaste?: () => void;
    globalVolume: number;
    globalMuted: boolean;
    showTipOfTheDay: boolean;
    onToggleTipOfTheDay: () => void;
    onToggleHistory?: () => void;
    historyVisible?: boolean;
    onAddFavourite: () => void;
    onToggleSearch?: () => void;
    searchVisible?: boolean;
    onViewSource?: () => void;
    onNewWindow?: (url?: string) => void;
    onSaveAs?: () => void;
    openModal: 'about' | null;
    setOpenModal: React.Dispatch<React.SetStateAction<'about' | null>>;
    plusTheme?: 'none' | 'aquarium' | 'davinci' | 'nature' | 'space';
}

const IEMenu = ({
    onNavigate,
    onBack,
    onForward,
    onHome,
    onOpen,
    onClose,
    onToggleFullscreen,
    onToggleFavourites,
    favouritesVisible,
    onToggleStatusBar,
    statusBarVisible,
    onToggleAddressBar,
    onToggleStandardToolbar,
    addressBarVisible,
    standardToolbarVisible,
    onRefresh,
    onStop,
    onCut,
    onCopy,
    onPaste,
    globalVolume,
    globalMuted,
    showTipOfTheDay,
    onToggleTipOfTheDay,
    onToggleHistory,
    historyVisible,
    onAddFavourite,
    searchVisible,
    onToggleSearch,
    onViewSource,
    onNewWindow,
    onSaveAs,
    openModal,
    setOpenModal,
    plusTheme,
    onError
}: IEMenuProps) => {
    const [openMenu, setOpenMenu] = useState<string | null>(null);
    const [hoveredItem, setHoveredItem] = useState<number | null>(null);
    const [showError, setShowError] = useState<ErrorType | null>(null);

    const sounds = useSound(globalVolume, globalMuted);
    const themeSound = plusTheme === 'aquarium' ? sounds.aquarium
        : plusTheme === 'davinci' ? sounds.daVinci
        : plusTheme === 'nature' ? sounds.nature
        : plusTheme === 'space' ? sounds.space
        : null;
    const playStartMenu = () => themeSound ? themeSound.playMenuCmd() : sounds.playStartMenu();
    const playError     = () => themeSound ? themeSound.playError()   : sounds.playError();
    const menuRef = useRef<HTMLDivElement>(null);

    // Close menu on outside click
    useEffect(() => {
        const handleClickOutside = (e: MouseEvent) => {
            if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
                setOpenMenu(null);
                setHoveredItem(null);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const closeMenu = () => {
        setOpenMenu(null);
        setHoveredItem(null);
    };

    const handleItemClick = (action?: string, url?: string) => {
        playStartMenu();
        if (url && onNavigate) { onNavigate(url); closeMenu(); return; }
        switch (action) {
            case 'back':             onBack?.();              break;
            case 'forward':          onForward?.();           break;
            case 'home':             onHome?.();              break;
            case 'open':             onOpen?.();              break;
            case 'close':            onClose?.();             break;
            case 'statusbar':        onToggleStatusBar?.();   break;
            case 'fullscreen':       onToggleFullscreen?.();  break;
            case 'favourites':       onToggleFavourites?.();  break;
            case 'refresh':          onRefresh?.();           break;
            case 'stop':             onStop?.();              break;
            case 'print':            onError?.('printerConnect'); break;
            case 'cut':              onCut?.();               break;
            case 'copy':             onCopy?.();              break;
            case 'paste':            onPaste?.();             break;
            case 'about':            setOpenModal('about');   break;
            case 'toolbar-standard': onToggleStandardToolbar?.(); break;
            case 'toolbar-address':  onToggleAddressBar?.();  break;
            case 'tipoftheday':      onToggleTipOfTheDay?.(); break;
            case 'history':          onToggleHistory?.();     break;
            case 'search':           onToggleSearch?.();      break;
            case 'add-favourite':    onAddFavourite?.();      break;
            case 'contents':         playError();             setShowError('webPageNotFound'); break;  
            case 'privacy-report':   playError();             setShowError('webPageNotFound'); break; 
            case 'source':           onViewSource?.(); break;   
            case 'new-window':       onNewWindow?.(undefined); break;
            case 'save-as':          onSaveAs?.(); break;
        }
        setOpenMenu(null);
    };

    return (
        <menu className='ie-menubar' ref={menuRef}>
            <ul className='ie-menu-list'>
                {menuData.map((menu) => (
                    <li
                        key={menu.id}
                        className={`ie-menu-item ${openMenu === menu.id ? 'is-open' : ''}`}
                    >
                        <button
                            type='button'
                            className='ie-menu-trigger'
                            onClick={() => {
                                setOpenMenu(openMenu === menu.id ? null : menu.id);
                                setHoveredItem(null);
                            }}
                        >
                            {menu.label}
                        </button>

                        {openMenu === menu.id && (
                            <ul className='ie-submenu'>
                                {menu.items.map((item, i) =>
                                    item.separator ? (
                                        <li key={i} className='separator' id='separator' />
                                    ) : (
                                        <li
                                            key={i}
                                            className={[
                                                'ie-submenu-item',
                                                item.disabled ? 'disabled' : '',
                                                item.icon ? 'has-icon' : '',
                                                item.action === 'statusbar' && statusBarVisible ? 'checked' : '',
                                                item.action === 'favourites' && favouritesVisible ? 'checked' : '',
                                                item.action === 'tipoftheday' && showTipOfTheDay ? 'checked' : '',
                                            ].filter(Boolean).join(' ')}
                                            onMouseEnter={() => setHoveredItem(i)}
                                            onMouseLeave={() => setHoveredItem(null)}
                                            onClick={() => handleItemClick(item.action, item.url)}
                                        >
                                            {item.icon && (
                                                <img
                                                    src={item.icon}
                                                    alt=''
                                                    className='menu-item-icon'
                                                />
                                            )}
                                            <span className='ie-submenu-label'>{item.label}</span>
                                            {item.shortcut && <span className='ie-submenu-shortcut'>{item.shortcut}</span>}
                                            {item.arrow && <span className='ie-submenu-arrow'>▸</span>}
                                            {item.checked && <span className='ie-submenu-check'>✓</span>}

                                            {item.children && hoveredItem === i && (
                                                <ul className='ie-submenu--nested'>
                                                    {item.children.map((child, j) =>
                                                        child.separator ? (
                                                            <li key={j} className='separator' />
                                                        ) : (
                                                            <li
                                                                key={j}
                                                                className={[
                                                                    'ie-submenu-item',
                                                                    child.disabled ? 'disabled' : '',
                                                                    child.action === 'toolbar-standard' && standardToolbarVisible ? 'checked' : '',
                                                                    child.action === 'toolbar-address' && addressBarVisible ? 'checked' : '',
                                                                    child.action === 'favourites' && favouritesVisible ? 'checked' : '',
                                                                    child.action === 'history' && historyVisible ? 'checked' : '',
                                                                    child.action === 'search' && searchVisible ? 'checked' : '',
                                                                ].filter(Boolean).join(' ')}
                                                                onClick={(e) => {
                                                                    e.stopPropagation();
                                                                    handleItemClick(child.action, child.url);
                                                                }}
                                                            >
                                                                {child.icon && (
                                                                    <img
                                                                        src={child.icon}
                                                                        alt=''
                                                                        className='menu-item-icon'
                                                                    />
                                                                )}
                                                                <span className='ie-submenu-label'>{child.label}</span>
                                                            </li>
                                                        )
                                                    )}
                                                </ul>
                                            )}
                                        </li>
                                    )
                                )}
                            </ul>
                        )}
                    </li>
                ))}
            </ul>

            {/* ABOUT MODAL */}
            {openModal === 'about' && (
                <AboutDialog
                    title='Internet Explorer'
                    onClose={() => setOpenModal(null)}
                />
            )}

            {/* ERROR MODAL */}
            {showError && (
                <CriticalError
                    type={showError}
                    onClose={() => setShowError(null)}
                />
            )}
        </menu>
    );
};

export default IEMenu;